import type { CLAIM_KINDS, ClaimStatus } from "../domain/constants";
import type { RegionConfig } from "../region/schema";

export type Refusal = { ok: false; reason: string };

export const SOURCE_LIVENESS = ["live", "gone", "unknown"] as const;
export type SourceLiveness = (typeof SOURCE_LIVENESS)[number];

/** Data for markup generated by our UI; never remote HTML. */
export type EmbedDescriptor =
  | { kind: "link"; url: string; placeId?: string }
  | { kind: "blockquote"; url: string; scriptUrl: string }
  | { kind: "iframe"; url: string };

export type SourceDescription = {
  platform: string;
  canonicalUrl: string;
  embed: EmbedDescriptor;
};

/** Describes links without copying content or permitting AI; matches must never fetch. */
export interface SourceAdapter {
  matches(url: string): boolean;
  describe(url: string): SourceDescription;
  liveness(canonicalUrl: string): Promise<SourceLiveness>;
  policy: {
    storesContent: false;
    aiAllowed: false;
    scriptHosts: readonly string[];
  };
}

export const GEO_SEARCH_MODES = ["submit", "typeahead"] as const;
export type GeoSearchMode = (typeof GEO_SEARCH_MODES)[number];
export const GEO_STORAGE_MODES = ["none", "reference-only", "full"] as const;
export type GeoStorageMode = (typeof GEO_STORAGE_MODES)[number];
export const CJK_MODES = ["hosted-glyphs", "localIdeographFontFamily"] as const;
export type CjkMode = (typeof CJK_MODES)[number];

export type GeoPolicy = {
  /** Maximum requests per second; enforced centrally. */
  rateLimit: number;
  userAgent: string;
  /** Cache lifetime in seconds. */
  cacheTtl: number;
  storage: GeoStorageMode;
};

/** Supplies a MapLibre style URL and CJK configuration; never omits attribution. */
export interface MapStyle {
  styleUrl(region: RegionConfig, theme: string, lang: string): string;
  attribution: readonly string[];
  glyphs: string | undefined;
  cjkMode: CjkMode;
}

export type GeoCandidate = {
  names: Record<string, string>;
  lat: number;
  lng: number;
  category: string;
  providerRef: string;
  attribution: readonly string[];
};

export type GeoSearchOptions = {
  bbox: RegionConfig["bbox"];
  countrycodes: RegionConfig["geo"]["countrycodes"];
  languages: RegionConfig["locales"];
  mode: GeoSearchMode;
};
export type GeoSearchResult = { ok: true; candidates: GeoCandidate[] } | Refusal;

/** Returns attributed suggestions, never truth; refuses typeahead unless policy permits it. */
export interface Search {
  search(query: string, options: GeoSearchOptions): Promise<GeoSearchResult>;
}

/** Resolves a person-dropped pin only; never establishes an authoritative location. */
export interface Reverse {
  reverse(lat: number, lng: number, languages: RegionConfig["locales"]): Promise<GeoCandidate[]>;
}

/** Separates style, search and reverse lookup; never stores provider output as truth. */
export interface GeoProvider {
  mapStyle: MapStyle;
  search: Search;
  reverse: Reverse;
  policy: GeoPolicy;
}

export type TranscriptSegment = { start: number; end: number; text: string };
export type Transcription = {
  text: string;
  segments: TranscriptSegment[];
  language: string;
  durationSeconds: number;
  modelVersion: string;
};

/** Transcribes consented audio; never returns text without language or assigns speakers. */
export interface Transcriber {
  transcribe(audio: Uint8Array, options: { language: string }): Promise<Transcription>;
}

export const TRANSLATOR_INPUT_KINDS = ["claim", "note", "live_chunk"] as const;
export type TranslatorInputKind = (typeof TRANSLATOR_INPUT_KINDS)[number];
export type TranslationItem = { itemId: string; text: string };
export type TranslatedItem = TranslationItem & { modelVersion: string };
export type TranslationOptions = {
  from: string;
  to: string;
  /** Original place name to its translation in the target language. */
  glossary: Readonly<Record<string, string>>;
  inputKind: TranslatorInputKind;
};
export type TranslationResult = { ok: true; items: TranslatedItem[] } | Refusal;

/** Translates eligible consented text only; refuses other kinds, never platform content.
 * Callers verify consent and eligibility; output stays labelled machine until human confirmation.
 */
export interface Translator {
  translate(items: TranslationItem[], options: TranslationOptions): Promise<TranslationResult>;
}

export type ExtractedClaim = {
  kind: (typeof CLAIM_KINDS)[number];
  cautionType?: RegionConfig["cautionVocabulary"][number]["key"];
  textOriginal: string;
  quote: string;
  spanStart: number;
  spanEnd: number;
};

/** Drops items without a nonempty quote matching the transcript span; never invents caution keys. */
export interface ClaimExtractor {
  extract(transcript: string, options: { regionConfig: RegionConfig }): Promise<ExtractedClaim[]>;
}

export const GROUNDING_VERDICTS = ["pass", "hold"] as const;
export type GroundingVerdict = (typeof GROUNDING_VERDICTS)[number];
export type GroundingSentence = { text: string; claimIds: string[] };
export type GroundingClaim = {
  id: string;
  status: ClaimStatus;
  textOriginal: string;
  quote: string;
};
export type GroundingResult = {
  sentenceIndex: number;
  verdict: GroundingVerdict;
  reasons: string[];
};

/** Checks published IDs, quotes and entailment with a different vendor; any failure holds, never opens. */
export interface GroundingChecker {
  check(sentences: GroundingSentence[], claims: GroundingClaim[]): Promise<GroundingResult[]>;
}

export type UploadTokenResult = { ok: true; uploadToken: string } | Refusal;

/** Authenticated, consent-gated audio access and withdrawal deletion; never issues an unconsented token. */
export interface Storage {
  putToken(path: string, contentType: string): Promise<UploadTokenResult>;
  stream(path: string): Promise<ReadableStream<Uint8Array>>;
  delete(path: string): Promise<void>;
}
